const item = $input.first().json || {};
const body = item.body || {};
const question = String((body.question || item.question || '')).trim();
const userId = String((body.userId || item.userId || '')).trim();
const actorRole = String((body.actorRole || item.actorRole || 'citizen')).toLowerCase();
const conversationId = body.conversationId || item.conversationId || 'CONV-' + Date.now().toString(36);
const errors = [];
if (!question) errors.push('question is required');
if (!userId) errors.push('userId is required');
if (!['citizen', 'surveyor', 'government', 'community', 'bank', 'admin'].includes(actorRole)) errors.push('actorRole is invalid');
if (errors.length > 0) {
  return [{ json: { __error: true, __status: 400, error: 'Validation failed: ' + errors.join('; '), conversationId: conversationId } }];
}
return [{ json: { __error: false, userId: userId, actorRole: actorRole, propertyUuid: body.propertyUuid || (body.context && body.context.selectedPropertyUuid) || (item.context && item.context.selectedPropertyUuid) || null, question: question, currentRoute: body.currentRoute || item.currentRoute || '/dashboard', context: body.context || item.context || {}, conversationId: conversationId, timestamp: new Date().toISOString() } }];

const input = $input.first().json || {};
const userId = String(input.userId || '');
const actorRole = String((input.actorRole || 'citizen')).toLowerCase();
const question = String(input.question || '');
const q = question.toLowerCase();
const context = input.context || {};
const propertyUuid = input.propertyUuid || null;
const clientProperties = Array.isArray(context.properties) ? context.properties : [];
let targetProperty = context.property || null;
if (!targetProperty && propertyUuid && clientProperties.length > 0) {
  targetProperty = clientProperties.find(function(p) { return p.id === propertyUuid || p.passportId === propertyUuid; }) || null;
}
if (!targetProperty && clientProperties.length > 0) {
  targetProperty = clientProperties.find(function(p) { return q.indexOf(String(p.title || '').toLowerCase()) !== -1 || q.indexOf(String(p.passportId || '').toLowerCase()) !== -1 || q.indexOf(String(p.address || '').toLowerCase()) !== -1; }) || clientProperties[0];
}
if (actorRole === 'citizen' && context.property && context.property.ownerId && context.property.ownerId !== userId) {
  return [{ json: { __error: true, __status: 403, error: 'Unauthorized: Citizens cannot access property records of other owners.', conversationId: input.conversationId || 'CONV' } }];
}
let data = {};
if (targetProperty) {
  data = {
    title: targetProperty.title || 'Selected Property',
    passportId: targetProperty.passportId || 'N/A',
    trustScore: targetProperty.trustScore || 0,
    status: targetProperty.status || 'pending',
    area: targetProperty.area || 0,
    valuationInr: targetProperty.valuation || 0,
    owner: targetProperty.owner || null,
    region: targetProperty.region || 'Karnataka',
    documents: Array.isArray(targetProperty.documents) ? targetProperty.documents : [],
    missingDocuments: Array.isArray(targetProperty.missingDocuments) ? targetProperty.missingDocuments : []
  };
}
return [{ json: { __error: false, __status: 200, conversationId: input.conversationId || 'CONV', userId: userId, actorRole: actorRole, propertyUuid: propertyUuid, question: question, currentRoute: input.currentRoute || '/dashboard', context: context, targetProperty: targetProperty, data: data } }];

const item = $input.first().json || {};
const question = String(item.question || '').toLowerCase();
const actorRole = String((item.actorRole || 'citizen')).toLowerCase();
const data = item.data || {};
const targetProperty = item.targetProperty || null;
const conversationId = item.conversationId || 'CONV';
const messageId = 'MSG-' + Date.now().toString(36);
const pTitle = String(data.title || (targetProperty && targetProperty.title) || 'Selected Property');
const passportId = String(data.passportId || (targetProperty && targetProperty.passportId) || 'N/A');
const trustScore = Number(data.trustScore || 0);
const status = String(data.status || 'pending').toLowerCase();
const valuationInr = Number(data.valuationInr || (targetProperty && targetProperty.valuation) || 0);
const missingDocs = Array.isArray(data.missingDocuments) ? data.missingDocuments : [];
let answer = 'I am Terra, your property intelligence assistant for ' + pTitle + ' (' + passportId + ').';
const suggestions = [];
const citations = [];
if (passportId !== 'N/A') citations.push({ label: pTitle, passportId: passportId });
if (question.includes('trust score') || question.includes('status') || question.includes('verification')) {
  if (status === 'verified') {
    answer = '**' + pTitle + '** (' + passportId + ') is fully VERIFIED with a Trust Score of **' + trustScore + '/100**.';
  } else if (status === 'manual_review' || status === 'pending') {
    answer = '**' + pTitle + '** (' + passportId + ') is under **' + status.toUpperCase() + '** with a Trust Score of **' + trustScore + '/100**.';
  } else {
    answer = '**' + pTitle + '** (' + passportId + ') is in **' + status.toUpperCase() + '** status with a Trust Score of **' + trustScore + '/100**.';
  }
  suggestions.push('What documents are still missing?');
  suggestions.push('What is the estimated valuation?');
} else if (question.includes('valuation') || question.includes('value') || question.includes('worth') || question.includes('price')) {
  answer = 'AI valuation for ' + pTitle + ': **INR ' + valuationInr.toLocaleString('en-IN') + '** estimated value.';
  suggestions.push('What is the current verification status?');
} else if (question.includes('document') || question.includes('missing') || question.includes('upload')) {
  answer = 'Document review for ' + pTitle + ' is in progress. Missing items: ' + (missingDocs.length ? missingDocs.join(', ') : 'None currently flagged.') + '.';
} else {
  answer = 'I am Terra, your property intelligence assistant for ' + pTitle + ' (' + passportId + '). Current status: ' + status.toUpperCase() + '. Trust Score: ' + trustScore + '/100.';
}
return [{ json: { success: true, conversationId: conversationId, messageId: messageId, answer: answer, role: actorRole, propertyUuid: targetProperty && targetProperty.id ? targetProperty.id : null, sources: ['properties'], data: data, citations: citations, suggestions: suggestions, generatedAt: new Date().toISOString() } }];
